// The typed client a module's `bench/*.ts` journeys call, one function per
// route `sofie bench` can reach. Regenerated by every run.
import http from 'k6/http';

const TARGET: string = __ENV.SOFIE_BENCH_TARGET;
const ACCOUNTS: Record<string, { email: string; password: string; signUp: boolean }> = JSON.parse(
  __ENV.SOFIE_BENCH_ACCOUNTS,
);

export interface Session<A extends string | null = string | null> {
  area: A;
  cookie: string;
}

export const ANONYMOUS: Session<null> = { area: null, cookie: '' };

// Signing up an address that exists changes nothing, so one local account serves every run.
export function signIn<A extends keyof typeof MEMBERS & string>(area: A): Session<A> {
  const member = MEMBERS[area];
  const account = ACCOUNTS[area];
  const credentials = JSON.stringify({ email: account.email, password: account.password });
  const params = {
    headers: { accept: 'application/json', 'content-type': 'application/json', origin: TARGET },
    redirects: 0,
  };
  if (account.signUp && member.signUp !== null) {
    http.post(TARGET + member.signUp, credentials, params);
  }
  const response = http.post(TARGET + member.signIn, credentials, params);
  const cookie = Object.entries(response.cookies)
    .map(([name, values]) => `${name}=${values[0].value}`)
    .join('; ');
  if (cookie === '') {
    throw new Error(`signing in to ${area} at ${member.signIn} answered ${response.status} without a session`);
  }
  return { area, cookie };
}

function send(session: Session, name: string, method: string, path: string, input?: unknown): unknown {
  const headers: Record<string, string> = { accept: 'application/json', traceparent: traceparent() };
  if (session.cookie !== '') {
    headers.cookie = session.cookie;
  }
  let body: string | null = null;
  if (method !== 'GET') {
    headers.origin = TARGET;
    headers['idempotency-key'] = uuid();
    if (input !== undefined) {
      headers['content-type'] = 'application/json';
      body = JSON.stringify(input);
    }
  }
  const response = http.request(method, TARGET + path, body, { headers, redirects: 0, tags: { name } });
  if (response.status >= 400) {
    throw new Error(`${name} answered ${response.status}`);
  }
  return typeof response.body === 'string' && response.body !== '' ? response.json() : undefined;
}

function fill(path: string, parameters: Record<string, string>): string {
  return path.replace(/\{(\w+)\}/g, (_, parameter: string) => encodeURIComponent(parameters[parameter]));
}

function traceparent(): string {
  return `00-${hex(32)}-${hex(16)}-01`;
}

function uuid(): string {
  return `${hex(8)}-${hex(4)}-4${hex(3)}-a${hex(3)}-${hex(12)}`;
}

function hex(length: number): string {
  let text = '';
  for (let index = 0; index < length; index += 1) {
    text += Math.floor(Math.random() * 16).toString(16);
  }
  return text;
}
